ee:variables.ee:set-variable:
%dw 2.0
output application/json
var p = payload default {}
var errors = [
    if (isEmpty(p.orderId)) "orderId is required and cannot be empty" else null,
    if (isEmpty(p.customerId)) "customerId is required and cannot be empty" else null,
    if (isEmpty(p.currency)) "currency is required (e.g., 'INR')" else null,
    if (isEmpty(p.totalAmount) or (p.totalAmount as Number default 0) <= 0) "totalAmount must be a positive number greater than 0" else null,
    if (isEmpty(p.items) or sizeOf(p.items default []) == 0) "items must contain at least one order line item" else null,
    if (!isEmpty(p.items) and (p.items some (item) -> isEmpty(item.sku) or (item.quantity as Number default 0) <= 0 or (item.unitPrice as Number default 0) < 0)) "each item in items must include sku, quantity > 0, and unitPrice >= 0" else null,
    if (isEmpty(p.payment)) "payment object is required" else null,
    if (!isEmpty(p.payment) and (isEmpty(p.payment.method) or isEmpty(p.payment.cardToken))) "payment must contain 'method' and 'cardToken'" else null,
    if (isEmpty(p.shipping)) "shipping object is required" else null,
    if (!isEmpty(p.shipping) and (isEmpty(p.shipping.addressLine1) or isEmpty(p.shipping.city) or isEmpty(p.shipping.state) or isEmpty(p.shipping.postalCode) or isEmpty(p.shipping.country) or isEmpty(p.shipping.serviceLevel))) "shipping must include addressLine1, city, state, postalCode, country, and serviceLevel" else null
] filter ($ != null)
---
errors

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    errorCode: "INVALID_REQUEST_PAYLOAD",
    errorMessage: "Order payload failed attribute validation",
    validationErrors: vars.validationErrors,
    correlationId: vars.tx.correlationId,
    timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"}
}

%dw 2.0
output application/json
---
{
    orderId: attributes.uriParams.orderId,
    status: "IN_PROGRESS",
    updatedAt: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"}
}
